WITH bo AS MATERIALIZED (SELECT o.id,o.customer_id,o.created_at FROM orders o WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01'), elig AS (SELECT DISTINCT bo.customer_id FROM bo JOIN order_items oi ON oi.order_id=bo.id JOIN products p ON p.id=oi.product_id AND p.active JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id AND s.risk_tier>=4 JOIN shipments sh ON sh.order_id=bo.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days'), cap AS (SELECT bo.customer_id,count(*) n FROM bo WHERE EXISTS (SELECT 1 FROM payments pay WHERE pay.order_id=bo.id AND pay.status='captured') GROUP BY bo.customer_id), rev AS (SELECT bo.customer_id,sum((oi.quantity-COALESCE(r.quantity,0))*oi.unit_price) n FROM bo JOIN order_items oi ON oi.order_id=bo.id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no WHERE EXISTS (SELECT 1 FROM payments pay WHERE pay.order_id=bo.id AND pay.status='captured') GROUP BY bo.customer_id), promo AS (SELECT bo.customer_id,sum(op.discount_amount) n FROM bo JOIN order_promotions op ON op.order_id=bo.id JOIN promotions pr ON pr.id=op.promotion_id AND pr.active GROUP BY bo.customer_id), late AS (SELECT bo.customer_id,count(*) n FROM bo JOIN shipments sh ON sh.order_id=bo.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days' GROUP BY bo.customer_id), risk AS (SELECT bo.customer_id,count(DISTINCT ps.supplier_id) n FROM bo JOIN order_items oi ON oi.order_id=bo.id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id AND s.risk_tier>=4 GROUP BY bo.customer_id), lasto AS (SELECT customer_id,max(created_at) n FROM bo GROUP BY customer_id) SELECT c.id AS customer_id,c.region,c.segment,COALESCE(cap.n,0::bigint) AS captured_order_count,COALESCE(rev.n,0)::numeric(20,2) AS net_item_revenue,COALESCE(promo.n,0)::numeric(18,2) AS active_promotion_discount,COALESCE(late.n,0::bigint) AS late_shipment_count,COALESCE(risk.n,0::bigint) AS risky_supplier_count,lasto.n AS last_completed_at FROM customers c JOIN elig e ON e.customer_id=c.id LEFT JOIN cap ON cap.customer_id=c.id LEFT JOIN rev ON rev.customer_id=c.id LEFT JOIN promo ON promo.customer_id=c.id LEFT JOIN late ON late.customer_id=c.id LEFT JOIN risk ON risk.customer_id=c.id LEFT JOIN lasto ON lasto.customer_id=c.id WHERE c.active